function i(r){const e=new Date(r);return Number.isNaN(e.getTime())?r:e.toISOString().replace("T"," ").replace(/\.\d+Z$/,"Z")}function o(r,e=new Date){const t=new Date(r);if(Number.isNaN(t.getTime()))return"";const n=e.getTime()-t.getTime();return n<3e5?"":a(n)}function s(r,e=new Date){const t=new Date(r);if(Number.isNaN(t.getTime()))return"";const n=e.getTime()-t.getTime();return n<=0?"0s":a(n)}function a(r){const e=Math.floor(r/1e3);if(e<60)return`${e}s`;const t=Math.floor(e/60);if(t<60)return`${t}m ${e%60}s`;const n=Math.floor(t/60);return n<24?`${n}h ${t%60}m`:`${Math.floor(n/24)}d ${n%24}h`}export{s as a,a as h,o as l,i as s};
